xql_query:
// ============================================================
// Rule: TRD_Automatic Alerts
// Vendor: Trend Micro
// Objective:
// Detect activity associated with TRD_Automatic Alerts.
// Severity: SEV_050_CRITICAL
// Category: OTHER
// ============================================================
// MITRE ATT&CK:
// Tactic: TA0040 - Impact
// Tactic: TA0002 - Execution
// Technique: T1204.002 - User Execution: Malicious File
// Technique: T1569.002 - System Services: Service Execution
// Tactic: TA0001 - Initial Access
// Technique: T1566 - Phishing

dataset = trend_micro_trend_vision_one_raw

// Filtra eventos Medium (5), High (7) e Critical (9) conforme padrão CEF do Trend
| filter to_number(cefseverity) >= 5

// Normaliza os campos para facilitar leitura e mapeamento no alerta
| alter
    alert_type      = cefname,                            // OAT, Audit, etc.
    alert_name      = cat,                                // Nome amigável da detecção
    severity_label  = if(cefseverity = "5", "MEDIUM",
                       if(cefseverity = "7", "HIGH",
                       if(cefseverity = "9", "CRITICAL", cefseverity))),
    severity_num    = to_number(cefseverity),
    host            = dvchost,
    process         = deviceprocessname,
    mitre_tactic    = if(cefname = "Trend Vision One Observed Attack Technique", cs1, null),
    mitre_technique = if(cefname = "Trend Vision One Observed Attack Technique", cs2, null),
    audit_user      = if(cefname contains "Audit Log", cs1, null),
    audit_role      = if(cefname contains "Audit Log", cs2, null),
    description     = msg,
    trend_alert_id  = externalid,
    trend_module    = devicefacility,
    event_time      = rt

// Campos finais exibidos no alerta
| fields _time, event_time, severity_label, severity_num, alert_type, alert_name,
         host, process, mitre_tactic, mitre_technique,
         audit_user, audit_role, trend_module, trend_alert_id, description
